// ValidateConfig validates all fields in Config according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateConfig(m *Config) error {
	return ValidateConfigWithDepth(m, 0)
}

// ValidateConfigWithDepth validates Config and carries nested-message depth across
// generated package boundaries.
func ValidateConfigWithDepth(m *Config, depth int) error {
	if m == nil {
		return nil
	}
	if depth > 24 {
		return protoerrors.NewErrMissingInvalidData(nil, "message nesting exceeds max depth of 24")
	}

	// Validate HazelcastMemoryMb (assert_ge: 256)
	if m.HazelcastMemoryMb < 256 {
		return protoerrors.NewErrMissingInvalidData(nil, "field HazelcastMemoryMb must be >= 256, got: %v", m.HazelcastMemoryMb)
	}
	// Validate MapIdleTtlSeconds (assert_ge: 60)
	if m.MapIdleTtlSeconds < 60 {
		return protoerrors.NewErrMissingInvalidData(nil, "field MapIdleTtlSeconds must be >= 60, got: %v", m.MapIdleTtlSeconds)
	}
	// Validate MaxMaps (assert_ge: 1)
	if m.MaxMaps < 1 {
		return protoerrors.NewErrMissingInvalidData(nil, "field MaxMaps must be >= 1, got: %v", m.MaxMaps)
	}
	// Validate RetentionDays (assert_ge: 1)
	if m.RetentionDays < 1 {
		return protoerrors.NewErrMissingInvalidData(nil, "field RetentionDays must be >= 1, got: %v", m.RetentionDays)
	}
	// Validate CleanupIntervalSeconds (assert_ge: 60)
	if m.CleanupIntervalSeconds < 60 {
		return protoerrors.NewErrMissingInvalidData(nil, "field CleanupIntervalSeconds must be >= 60, got: %v", m.CleanupIntervalSeconds)
	}
	// Validate ActiveSessionIdleSeconds (assert_ge: 30)
	if m.ActiveSessionIdleSeconds < 30 {
		return protoerrors.NewErrMissingInvalidData(nil, "field ActiveSessionIdleSeconds must be >= 30, got: %v", m.ActiveSessionIdleSeconds)
	}
	// Validate TraceId (default max size: 32768 bytes)
	if len(m.TraceId) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field TraceId exceeds max size of 32768 bytes, got: %d", len(m.TraceId))
	}

	return nil
}

